 try:
  x=json.load(open(f)); v=x.get('validation',{}); m=v.get('metrics',{}); a=x.get('benchmark_admission',{}).get('selected_metrics',{})
  print(os.path.basename(f), 'IC',m.get('ic_mean_daily'),'ICIR',m.get('icir_daily'),'q',a.get('quality'),'corr',m.get('max_abs_library_correlation'),'turn',m.get('turnover_rank_mean_abs_change'), 'status',v.get('status'))
 except Exception as e: print(e)
PY

